db_path = DATA_DIR / Path("_repo_size_cache.sqlite3")
cached_rows = load_cache(cache_path)
init_db(db_path)
for repo_key, metadata in cached_rows.items():
    repo_id, sha = repo_key.split("@")
    size, siblings = metadata["size"], metadata["siblings"]
    error = f"[RepositoryNotFoundError] {repo_id}" if repo_id in repos_not_accessible else ""
    save_to_cache(db_path, repo_id, sha, size, siblings, error)
